[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$ProjectPath,
    [Parameter(Mandatory=$true)][string]$VerificationRoot,
    [Parameter(Mandatory=$true)][string]$PilotRoot,
    [Parameter(Mandatory=$true)][string]$PilotPlanPath,
    [Parameter(Mandatory=$true)][string]$ProvenancePath,
    [switch]$BindingSmokeOnly
)

$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
if([string]::IsNullOrWhiteSpace($ProjectPath)-or-not[IO.Path]::IsPathRooted($ProjectPath)){throw 'Gate12R post-pilot audit requires an explicit absolute ProjectPath.'}
$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate12RPostPilotReadinessAuditV2|$ProjectPath");exit 0}
$VerificationRoot=[IO.Path]::GetFullPath($VerificationRoot);$PilotRoot=[IO.Path]::GetFullPath($PilotRoot);$PilotPlanPath=[IO.Path]::GetFullPath($PilotPlanPath);$ProvenancePath=[IO.Path]::GetFullPath($ProvenancePath)
Import-Module (Join-Path $ProjectPath 'Research\Gate12RProcessReusePreparationV2.psm1') -Force
$plan=Read-Gate12RJson $PilotPlanPath;$provenance=Read-Gate12RJson $ProvenancePath
$summaryPath=Join-Path $VerificationRoot 'PostPilotReadinessAudit.summary.json';if(Test-Path $summaryPath){throw "Create-new post-pilot audit exists: $summaryPath"}
$failures=New-Object Collections.Generic.List[string];$checks=New-Object Collections.Generic.List[object]
function Check([string]$Id,[bool]$Passed,[string]$Evidence){$checks.Add([pscustomobject]@{id=$Id;passed=$Passed;evidence=$Evidence});if(-not$Passed){$failures.Add("$Id`: $Evidence")}}
try{
    Check 'formal-root-absent' (-not(Test-Path (Join-Path $ProjectPath ([string]$plan.paths.reservedFormalRootRelativePath).Replace('/','\')))) 'Gate13R formal root absent'
    Check 'unity-closed' (@(Get-Process -Name Unity -ErrorAction SilentlyContinue).Count-eq0) 'no Unity processes'
    Check 'lock-absent' (-not(Test-Path (Join-Path $ProjectPath 'Temp\UnityLockfile'))) 'Unity project lock absent'
    foreach($binding in @($provenance.boundFiles)){$path=Join-Path $ProjectPath ([string]$binding.relativePath).Replace('/','\');Check ('binding-'+[string]$binding.id) ((Test-Path $path)-and(Get-Gate12RLowerSha256 $path)-eq[string]$binding.sha256) ([string]$binding.relativePath)}
    $executionPath=Join-Path $PilotRoot 'pilot-execution-manifest.json';$execution=Read-Gate12RJson $executionPath;Check 'execution-complete' ($execution.completed-eq$true-and[int]$execution.totalUnityProcessCount-eq429-and[int]$execution.totalSampleCount-eq1212-and[int]$execution.measuredBlockProcessCount-eq384-and[int]$execution.measuredSampleCount-eq1152) (Get-Gate12RLowerSha256 $executionPath)
    Check 'execution-boundary' ($execution.formalCampaign-eq$false-and$execution.excludedFromFormalAnalysis-eq$true-and$execution.gate13rAuthorized-eq$false-and[int]$execution.automaticRetryCount-eq0-and[int]$execution.automaticResumeCount-eq0) 'NON-FORMAL / EXCLUDED / no retry or resume'
    $entries=@($execution.entries);Check 'entry-cardinality' ($entries.Count-eq428-and@($entries|Where-Object role -eq 'excluded-warmup').Count-eq8-and@($entries|Where-Object role -eq 'excluded-cold-structural-control').Count-eq36-and@($entries|Where-Object role -eq 'measured-non-formal-pilot').Count-eq384) '8 warmup + 36 cold + 384 measured'
    foreach($entry in $entries){$output=Join-Path $ProjectPath ([string]$entry.outputRelativePath).Replace('/','\');$wrapper=Join-Path $ProjectPath ([string]$entry.wrapperSummaryRelativePath).Replace('/','\');Check ('entry-wrapper-'+[string]$entry.ordinal+'-'+[string]$entry.role) ((Test-Path $wrapper)-and(Get-Gate12RLowerSha256 $wrapper)-eq[string]$entry.wrapperSummarySha256) ([string]$entry.wrapperSummaryRelativePath);if([string]$entry.role-ne'excluded-cold-structural-control'){$manifest=Join-Path $output 'block-manifest.json';Check ('entry-manifest-'+[string]$entry.ordinal) ((Test-Path $manifest)-and(Get-Gate12RLowerSha256 $manifest)-eq[string]$entry.blockManifestSha256) ([string]$entry.blockId)}else{$manifest=Join-Path $output 'manifest.json';$result=Join-Path $output 'workload-result.json';Check ('cold-hashes-'+[string]$entry.ordinal) ((Get-Gate12RLowerSha256 $manifest)-eq[string]$entry.manifestSha256-and(Get-Gate12RLowerSha256 $result)-eq[string]$entry.workloadResultSha256) ([string]$entry.runId)}}
    foreach($campaign in @($plan.campaignIds)){$blocks=@($entries|Where-Object {$_.role-eq'measured-non-formal-pilot'-and$_.campaignId-eq$campaign});Check ('campaign-blocks-'+$campaign) ($blocks.Count-eq32-and@($blocks.block|Sort-Object -Unique).Count-eq32) '32 independent complete Williams blocks'}
    $pilotManifestPath=Join-Path $PilotRoot 'pilot-manifest.json';$pilotManifest=Read-Gate12RJson $pilotManifestPath;Check 'pilot-manifest' ($pilotManifest.completed-eq$true-and$pilotManifest.formalCampaign-eq$false-and$pilotManifest.excludedFromFormalAnalysis-eq$true-and$pilotManifest.gate13rAuthorized-eq$false-and[int]$pilotManifest.measuredBlockCount-eq384-and[int]$pilotManifest.measuredSampleCount-eq1152) (Get-Gate12RLowerSha256 $pilotManifestPath)
    $analysisPath=Join-Path $PilotRoot 'block-aware-analysis.json';$analysis=Read-Gate12RJson $analysisPath;Check 'block-aware-analysis' ($analysis.passed-eq$true-and[int]$analysis.structuralComparisonCount-eq1152-and[int]$analysis.structuralMismatchCount-eq0-and$analysis.hardCap-eq$null) (Get-Gate12RLowerSha256 $analysisPath)
    $candidatePath=Join-Path $PilotRoot 'candidate-n-formal.json';$candidate=Read-Gate12RJson $candidatePath;Check 'candidate-policy' ($candidate.passed-eq$true-and$candidate.hardCap-eq$null-and[double]$candidate.precisionTargetRelativeHalfWidth-eq0.05-and@($candidate.cohorts).Count-eq3) (Get-Gate12RLowerSha256 $candidatePath);foreach($cohort in @($candidate.cohorts)){Check ('candidate-'+[string]$cohort.comparisonCohortId) ([long]$cohort.candidateNFormal-ge32-and[long]$cohort.candidateNFormal%4-eq0-and$null-eq$cohort.hardCap) ("n=$($cohort.candidateNFormal)")}
    $correlationPath=Join-Path $PilotRoot 'correlation-diagnostics.json';$correlation=Read-Gate12RJson $correlationPath;Check 'correlation-diagnostics' ($correlation.passed-eq$true-and@($correlation.diagnostics.campaigns).Count-eq12) (Get-Gate12RLowerSha256 $correlationPath)
    $budgetPath=Join-Path $PilotRoot 'budget-storage-projection.json';$budget=Read-Gate12RJson $budgetPath;Check 'budget-storage' ($budget.passed-eq$true-and$budget.storageFeasible-eq$true-and@($budget.rows).Count-eq3) (Get-Gate12RLowerSha256 $budgetPath)
    $start=Read-Gate12RJson (Join-Path $PilotRoot 'environment-start.json');$warm=Read-Gate12RJson (Join-Path $PilotRoot 'environment-post-warmup.json');$end=Read-Gate12RJson (Join-Path $PilotRoot 'environment-end.json');Check 'environment-start' ($start.passed-eq$true-and[int]$start.acLineStatus-eq1) 'start preflight passed on AC';Check 'environment-post-warmup' ($warm.passed-eq$true-and[int]$warm.acLineStatus-eq1) 'post-warmup preflight passed on AC';Check 'environment-end-recorded' ($null-ne$end.outputDriveFreeBytes-and$null-ne$end.powerSchemeGuid) 'end state recorded'
    $playable=Read-Gate12RJson (Join-Path $VerificationRoot 'StaticUnit\playable-mapping-validation.json');Check 'playable-validation' ($playable.passed-eq$true-and[int]$playable.campaignCount-eq12) '12/12 pilot campaign mappings valid'
    $retained=Read-Gate12RJson (Join-Path $VerificationRoot 'BlockAndRegression\RetainedRegression\wrapper.json');Check 'retained-63' ($retained.passed-eq$true-and[int]$retained.assertionCount-eq63) 'retained regression 63/63'
    $partial=Read-Gate12RJson (Join-Path $PilotRoot 'partial-output-manifest.json');$partialMismatch=0;foreach($file in @($partial.files)){$path=Join-Path $ProjectPath ([string]$file.relativePath).Replace('/','\');if(-not(Test-Path $path)-or(Get-Gate12RLowerSha256 $path)-ne[string]$file.sha256){$partialMismatch++}};Check 'partial-manifest-hashes' ($partialMismatch-eq0) ("files=$($partial.fileCount) mismatches=$partialMismatch")
}catch{$failures.Add($_.Exception.ToString())}
$summary=[ordered]@{schemaVersion=1;summaryKind='gate12r-post-pilot-readiness-audit-v1';savedAtUtc=[DateTime]::UtcNow.ToString('o');pilotPlanSha256=Get-Gate12RLowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate12RLowerSha256 $ProvenancePath;pilotRoot=$PilotRoot;checkCount=$checks.Count;checks=$checks.ToArray();failureCount=$failures.Count;failures=$failures.ToArray();gate12rPassed=$failures.Count-eq0;gate13rAuthorized=$false;formalRootCreated=$false;passed=$failures.Count-eq0}
Write-Gate12RAtomicUtf8NoBomJson -Path $summaryPath -Value $summary -Depth 50
if($failures.Count){Write-Error("Gate12R post-pilot readiness audit failed: "+($failures-join'; '));exit 1}

$candidate=Read-Gate12RJson (Join-Path $PilotRoot 'candidate-n-formal.json');$budget=Read-Gate12RJson (Join-Path $PilotRoot 'budget-storage-projection.json')
$readinessPath=Join-Path $ProjectPath 'Research\Gate12R_Readiness_Checkpoint.v1.json';if(Test-Path $readinessPath){throw 'Gate12R readiness checkpoint already exists; refusing overwrite.'}
$readiness=[ordered]@{schemaVersion=1;checkpointKind='gate12r-process-reuse-5pct-readiness-checkpoint-v1';status='GATE12R-PASSED-GATE13R-NOT-AUTHORIZED';completedAtUtc=[DateTime]::UtcNow.ToString('o');executionDesignId=[string]$plan.executionDesignId;pilotRoot=Get-Gate12RProjectRelativePath $ProjectPath $PilotRoot;pilotManifestSha256=Get-Gate12RLowerSha256 (Join-Path $PilotRoot 'pilot-manifest.json');postPilotAuditRelativePath=Get-Gate12RProjectRelativePath $ProjectPath $summaryPath;postPilotAuditSha256=Get-Gate12RLowerSha256 $summaryPath;measuredBlockCount=384;measuredSampleCount=1152;totalUnityProcessCount=429;precisionTarget='5-percent-relative-half-width';hardCap=$null;candidateNFormal=@($candidate.cohorts);budgetStorage=@($budget.rows);playableCampaignMappingCount=12;formalCampaign=$false;pilotExcludedFromFormalAnalysis=$true;gate13rAuthorized=$false;gate13rFormalRootCreated=$false;nextAction='request-separate-user-authorization-for-gate13r'}
Write-Gate12RAtomicUtf8NoBomJson -Path $readinessPath -Value $readiness -Depth 40
$checkpoint=Read-Gate12RJson (Join-Path $PilotRoot 'pilot-checkpoint.json');$checkpoint.status='GATE12R-COMPLETE-GATE13R-NOT-AUTHORIZED';$checkpoint.savedAtUtc=[DateTime]::UtcNow.ToString('o');$checkpoint|Add-Member -NotePropertyName readinessCheckpointRelativePath -NotePropertyValue (Get-Gate12RProjectRelativePath $ProjectPath $readinessPath) -Force;$checkpoint|Add-Member -NotePropertyName readinessCheckpointSha256 -NotePropertyValue (Get-Gate12RLowerSha256 $readinessPath) -Force;Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $PilotRoot 'pilot-checkpoint.json') -Value $checkpoint -Depth 40
$files=@(Get-ChildItem -LiteralPath $PilotRoot -Recurse -File -Force);$rows=New-Object Collections.Generic.List[object];foreach($file in $files){$rows.Add([pscustomobject]@{relativePath=Get-Gate12RProjectRelativePath $ProjectPath $file.FullName;rawBytes=[long]$file.Length;sha256=Get-Gate12RLowerSha256 $file.FullName})};$evidence=[ordered]@{schemaVersion=1;manifestKind='gate12r-final-pilot-evidence-manifest-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');pilotRoot=Get-Gate12RProjectRelativePath $ProjectPath $PilotRoot;fileCount=$rows.Count;rawBytes=[long](($files|Measure-Object Length -Sum).Sum);files=$rows.ToArray();formalCampaign=$false;gate13rAuthorized=$false};Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $VerificationRoot 'Gate12R_Final_Pilot_Evidence_Manifest.v1.json') -Value $evidence -Depth 20
Write-Host "Gate12R passed final readiness audit ($($checks.Count) checks); Gate13R remains unauthorized." -ForegroundColor Green
exit 0
